    @OneToMany(fetch = FetchType.EAGER) @JoinColumn(name = "subrogations") var subrogations:  Set<SubrogationRecovery>? = null,
    @Enumerated(EnumType.STRING) var partyType: ThirdPartyType? = null
)

@Entity
data class Document(
    @Id var documentId: UUID? = null,
    var fileName: String? = null,
    var uploadedDate:  Date? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "policy") var policy: Policy? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "claim") var claim: Claim? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "application") var application: Application? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "customer") var customer: Customer? = null,
    @Enumerated(EnumType.STRING) var documentType: DocumentType? = null
)

